PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE settings (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  competition_code TEXT,
  competition_id INTEGER,
  competition_name TEXT,
  season INTEGER NOT NULL,
  exact_points INTEGER NOT NULL DEFAULT 3,
  outcome_points INTEGER NOT NULL DEFAULT 1,
  lock_minutes INTEGER NOT NULL DEFAULT 0,
  last_sync_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE players (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  name_normalized TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE matches (
  id TEXT PRIMARY KEY,
  source_match_id INTEGER NOT NULL,
  competition_code TEXT NOT NULL,
  competition_name TEXT,
  season INTEGER NOT NULL,
  utc_date TEXT NOT NULL,
  stage TEXT,
  status TEXT NOT NULL,
  home_team TEXT NOT NULL,
  away_team TEXT NOT NULL,
  score_home INTEGER,
  score_away INTEGER,
  matchday INTEGER,
  last_synced_at TEXT NOT NULL
);
CREATE TABLE standings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  competition_code TEXT NOT NULL,
  season INTEGER NOT NULL,
  label TEXT NOT NULL,
  sort_order INTEGER NOT NULL,
  rows_json TEXT NOT NULL,
  last_synced_at TEXT NOT NULL
);
CREATE TABLE predictions (
  id TEXT PRIMARY KEY,
  player_id TEXT NOT NULL,
  match_id TEXT NOT NULL,
  home_goals INTEGER NOT NULL,
  away_goals INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (player_id, match_id)
);
CREATE TABLE sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE leagues (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  competition_code TEXT NOT NULL,
  competition_id INTEGER,
  competition_name TEXT,
  season INTEGER NOT NULL,
  exact_points INTEGER NOT NULL DEFAULT 3,
  outcome_points INTEGER NOT NULL DEFAULT 1,
  lock_minutes INTEGER NOT NULL DEFAULT 0,
  last_sync_at TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_by_user_id TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, organization_id TEXT);
CREATE TABLE league_memberships (
  user_id TEXT NOT NULL,
  league_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id, league_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (league_id) REFERENCES leagues(id) ON DELETE CASCADE
);
CREATE TABLE league_matches (
  id TEXT PRIMARY KEY,
  league_id TEXT NOT NULL,
  source_match_id INTEGER NOT NULL,
  competition_code TEXT NOT NULL,
  competition_name TEXT,
  season INTEGER NOT NULL,
  utc_date TEXT NOT NULL,
  stage TEXT,
  status TEXT NOT NULL,
  home_team TEXT NOT NULL,
  away_team TEXT NOT NULL,
  score_home INTEGER,
  score_away INTEGER,
  matchday INTEGER,
  last_synced_at TEXT NOT NULL,
  FOREIGN KEY (league_id) REFERENCES leagues(id) ON DELETE CASCADE
);
CREATE TABLE league_standings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  league_id TEXT NOT NULL,
  label TEXT NOT NULL,
  sort_order INTEGER NOT NULL,
  rows_json TEXT NOT NULL,
  last_synced_at TEXT NOT NULL,
  FOREIGN KEY (league_id) REFERENCES leagues(id) ON DELETE CASCADE
);
CREATE TABLE league_predictions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  match_id TEXT NOT NULL,
  home_goals INTEGER NOT NULL,
  away_goals INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (user_id, match_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (match_id) REFERENCES league_matches(id) ON DELETE CASCADE
);
CREATE TABLE organizations (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "users" (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  email_normalized TEXT NOT NULL UNIQUE,
  display_name TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  password_salt TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('superadmin', 'admin', 'user')),
  is_active INTEGER NOT NULL DEFAULT 1,
  organization_id TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, must_change_password INTEGER NOT NULL DEFAULT 0, password_changed_at TEXT);
CREATE TABLE password_reset_requests (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  organization_id TEXT,
  email_normalized TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'resolved')),
  requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  resolved_at TEXT,
  resolved_by_user_id TEXT,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE audit_logs (
  id TEXT PRIMARY KEY,
  organization_id TEXT,
  actor_user_id TEXT,
  actor_role TEXT NOT NULL,
  actor_display_name TEXT,
  action_type TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_id TEXT,
  entity_label TEXT,
  details_json TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_matches_competition_season_date
  ON matches (competition_code, season, utc_date);
CREATE INDEX idx_standings_competition_season
  ON standings (competition_code, season, sort_order);
CREATE INDEX idx_predictions_match
  ON predictions (match_id);
CREATE INDEX idx_predictions_player
  ON predictions (player_id);
CREATE INDEX idx_sessions_user_id ON sessions(user_id);
CREATE INDEX idx_sessions_expires_at ON sessions(expires_at);
CREATE INDEX idx_leagues_slug ON leagues(slug);
CREATE INDEX idx_leagues_active ON leagues(is_active);
CREATE INDEX idx_league_memberships_league_id ON league_memberships(league_id);
CREATE INDEX idx_league_matches_league_date
  ON league_matches (league_id, utc_date);
CREATE INDEX idx_league_standings_league_sort
  ON league_standings (league_id, sort_order);
CREATE INDEX idx_league_predictions_user_match
  ON league_predictions (user_id, match_id);
CREATE INDEX idx_league_predictions_match
  ON league_predictions (match_id);
CREATE INDEX idx_leagues_organization_id ON leagues(organization_id);
CREATE INDEX idx_users_organization_id ON users(organization_id);
CREATE INDEX idx_password_reset_requests_org_status
  ON password_reset_requests (organization_id, status, requested_at);
CREATE INDEX idx_password_reset_requests_user_status
  ON password_reset_requests (user_id, status);
CREATE INDEX idx_audit_logs_org_created_at
  ON audit_logs (organization_id, created_at DESC);
CREATE INDEX idx_audit_logs_actor_created_at
  ON audit_logs (actor_user_id, created_at DESC);
CREATE INDEX idx_audit_logs_entity_created_at
  ON audit_logs (entity_type, entity_id, created_at DESC);
